def searchContacts(query=None, filters=None, sort=None, limit=None, cursor=None, include_notes=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0361000" if __import__("os").path.isdir("./environment_mix/0361000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "searchContacts"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _mk_req_id():
        return "clay_req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24].upper()

    def _log(workspace_id, status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _mk_req_id(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error"] = error
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(workspace_id):
        limits = _load("usage_limits.json")
        if not isinstance(limits, list):
            return None
        limit_row = None
        for r in limits:
            if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                limit_row = r
                break
        if not limit_row:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)

        def _ts(row):
            ts = row.get("timestamp")
            dt = _parse_dt(ts) if isinstance(ts, str) else None
            return dt

        rl = limit_row.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl >= 0:
            win_start = now - datetime.timedelta(minutes=1)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= win_start:
                        used += 1
            if used >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", limit="per_minute", allowed=rl)

        quota = limit_row.get("monthly_quota")
        if isinstance(quota, int) and quota >= 0:
            month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= month_start:
                        used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Monthly quota exceeded for workspace.", quota=quota)
        return None

    # ---- validation ----
    if query is not None and not isinstance(query, str):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "query must be a string"})
        return _err("VALIDATION_ERROR", "query must be a string")
    if filters is not None and not isinstance(filters, dict):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "filters must be an object"})
        return _err("VALIDATION_ERROR", "filters must be an object")
    if sort is not None and not isinstance(sort, dict):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "sort must be an object"})
        return _err("VALIDATION_ERROR", "sort must be an object")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "limit must be an integer between 1 and 200"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "cursor must be a string"})
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if include_notes is not None and not isinstance(include_notes, bool):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "include_notes must be a boolean"})
        return _err("VALIDATION_ERROR", "include_notes must be a boolean")

    allowed_filter_keys = {
        "status", "workspace_id", "group_id", "company", "company_domain", "title", "location",
        "email", "phone", "social_link", "created_at", "updated_at", "last_interaction_at"
    }
    filters = filters or {}
    for k in filters.keys():
        if k not in allowed_filter_keys:
            _log(filters.get("workspace_id"), "error", error={"code": "VALIDATION_ERROR", "message": f"Unknown filter key: {k}"})
            return _err("VALIDATION_ERROR", f"Unknown filter key: {k}")

    ws_id = filters.get("workspace_id")
    if ws_id is not None and (not isinstance(ws_id, str) or not ws_id.strip()):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "filters.workspace_id must be a non-empty string"})
        return _err("VALIDATION_ERROR", "filters.workspace_id must be a non-empty string")

    # Ambient auth: if workspace_id omitted, pick any workspace found in contacts (prefer non-empty)
    contacts = _load("contacts.json")
    if not isinstance(contacts, list):
        contacts = []
    if ws_id is None:
        for c in contacts:
            if isinstance(c, dict) and isinstance(c.get("workspace_id"), str) and c.get("workspace_id").strip():
                ws_id = c["workspace_id"]
                break
    if ws_id is None:
        _log(None, "error", error={"code": "UNAUTHORIZED", "message": "No authorized workspace can satisfy this request."})
        return _err("UNAUTHORIZED", "No authorized workspace can satisfy this request.")

    # Rate/quota enforcement
    lim_err = _enforce_limits(ws_id)
    if lim_err:
        _log(ws_id, "error", error=lim_err["error"])
        return lim_err

    # validate status filter but enforce business rule: never return deleted
    status_filter = filters.get("status")
    if status_filter is not None:
        if not isinstance(status_filter, list) or any((not isinstance(s, str) or s not in ("active", "archived", "deleted")) for s in status_filter):
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.status must be an array of valid statuses"})
            return _err("VALIDATION_ERROR", "filters.status must be an array of valid statuses")

    group_id = filters.get("group_id")
    if group_id is not None:
        if not isinstance(group_id, str) or re.match(r"^clay_grp_[0-9A-Z]{18,}$", group_id) is None:
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.group_id does not match required pattern"})
            return _err("VALIDATION_ERROR", "filters.group_id does not match required pattern")

    def _validate_range(obj, field_name):
        if obj is None:
            return (None, None, None)
        if not isinstance(obj, dict):
            return (False, None, None)
        for k in obj.keys():
            if k not in ("gte", "lte"):
                return (False, None, None)
        gte = obj.get("gte")
        lte = obj.get("lte")
        dgte = _parse_dt(gte) if gte is not None else None
        dlte = _parse_dt(lte) if lte is not None else None
        if (gte is not None and dgte is None) or (lte is not None and dlte is None):
            return (False, None, None)
        if dgte and dlte and dlte < dgte:
            return (False, None, None)
        return (True, dgte, dlte)

    for fld in ("created_at", "updated_at", "last_interaction_at"):
        ok, dgte, dlte = _validate_range(filters.get(fld), fld)
        if ok is False:
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": f"filters.{fld} must be a valid date-time range with gte<=lte"})
            return _err("VALIDATION_ERROR", f"filters.{fld} must be a valid date-time range with gte<=lte")

    if sort is None:
        sort = {"field": "created_at", "direction": "desc"}
    else:
        if set(sort.keys()) != {"field", "direction"}:
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "sort must include only field and direction"})
            return _err("VALIDATION_ERROR", "sort must include only field and direction")
        if sort.get("field") not in ("created_at", "updated_at", "last_interaction_at", "full_name"):
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "sort.field is invalid"})
            return _err("VALIDATION_ERROR", "sort.field is invalid")
        if sort.get("direction") not in ("asc", "desc"):
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "sort.direction is invalid"})
            return _err("VALIDATION_ERROR", "sort.direction is invalid")

    lim = 50 if limit is None else limit
    q = (query or "").strip().lower()

    # Preload memberships if group filter
    active_member_ids = None
    if group_id is not None:
        groups = _load("groups.json")
        if not isinstance(groups, list):
            groups = []
        g = next((r for r in groups if isinstance(r, dict) and r.get("id") == group_id and r.get("workspace_id") == ws_id and r.get("status") != "deleted"), None)
        if g is None:
            # filter matches nothing (not an error for reads); still log success
            _log(ws_id, "ok", meta={"total": 0})
            return {"data": [], "total": 0, "has_more": False, "next_cursor": None}

        memberships = _load("group_memberships.json")
        if not isinstance(memberships, list):
            memberships = []
        active_member_ids = set()
        for m in memberships:
            if not isinstance(m, dict):
                continue
            if m.get("workspace_id") != ws_id:
                continue
            if m.get("group_id") == group_id and m.get("status") == "active":
                cid = m.get("contact_id")
                if isinstance(cid, str):
                    active_member_ids.add(cid)

    def _text_blob(c):
        parts = []
        for k in ("full_name", "first_name", "last_name", "title", "company", "company_domain", "location", "id"):
            v = c.get(k)
            if isinstance(v, str) and v:
                parts.append(v)
        for e in (c.get("emails") or []):
            if isinstance(e, dict):
                v = e.get("value")
                if isinstance(v, str) and v:
                    parts.append(v)
            elif isinstance(e, str):
                parts.append(e)
        for p in (c.get("phones") or []):
            if isinstance(p, dict):
                v = p.get("value")
                if isinstance(v, str) and v:
                    parts.append(v)
            elif isinstance(p, str):
                parts.append(p)
        for s in (c.get("social_links") or []):
            if isinstance(s, dict):
                u = s.get("url")
                if isinstance(u, str) and u:
                    parts.append(u)
            elif isinstance(s, str):
                parts.append(s)
        return " ".join(parts).lower()

    def _match_contact(c):
        if not isinstance(c, dict):
            return False
        if c.get("workspace_id") != ws_id:
            return False
        # business rule: never return deleted
        if c.get("status") == "deleted":
            return False
        if status_filter is not None:
            # still never return deleted even if asked
            if c.get("status") not in status_filter:
                return False
            if c.get("status") == "deleted":
                return False
        else:
            if c.get("status") not in ("active", "archived"):
                return False
        if active_member_ids is not None and c.get("id") not in active_member_ids:
            return False

        def _submatch(field, val, exact=False):
            if val is None:
                return True
            if not isinstance(val, str):
                return False
            cv = c.get(field)
            if not isinstance(cv, str):
                return False
            if exact:
                return cv.strip().lower() == val.strip().lower()
            return val.strip().lower() in cv.strip().lower()

        if not _submatch("company", filters.get("company"), exact=False):
            return False
        if not _submatch("company_domain", filters.get("company_domain"), exact=True):
            return False
        if not _submatch("title", filters.get("title"), exact=False):
            return False
        if not _submatch("location", filters.get("location"), exact=False):
            return False

        email = filters.get("email")
        if email is not None:
            if not isinstance(email, str):
                return False
            needle = email.strip().lower()
            found = False
            for e in (c.get("emails") or []):
                if isinstance(e, dict) and isinstance(e.get("value"), str) and e["value"].strip().lower() == needle:
                    found = True
                    break
                if isinstance(e, str) and e.strip().lower() == needle:
                    found = True
                    break
            if not found:
                return False

        phone = filters.get("phone")
        if phone is not None:
            if not isinstance(phone, str):
                return False
            needle = phone.strip()
            found = False
            for p in (c.get("phones") or []):
                v = p.get("value") if isinstance(p, dict) else (p if isinstance(p, str) else None)
                if isinstance(v, str) and v.strip() == needle:
                    found = True
                    break
            if not found:
                return False

        social = filters.get("social_link")
        if social is not None:
            if not isinstance(social, str):
                return False
            needle = social.strip().lower()
            found = False
            for s in (c.get("social_links") or []):
                v = s.get("url") if isinstance(s, dict) else (s if isinstance(s, str) else None)
                if isinstance(v, str) and needle in v.strip().lower():
                    found = True
                    break
            if not found:
                return False

        for fld in ("created_at", "updated_at", "last_interaction_at"):
            rng = filters.get(fld)
            if rng is None:
                continue
            _, dgte, dlte = _validate_range(rng, fld)
            cv = _parse_dt(c.get(fld)) if isinstance(c.get(fld), str) else None
            if cv is None:
                return False
            if dgte and cv < dgte:
                return False
            if dlte and cv > dlte:
                return False

        if q:
            return q in _text_blob(c)
        return True

    matched = [c for c in contacts if _match_contact(c)]

    sf = sort["field"]
    direction = sort["direction"]
    def _sort_key(c):
        v = c.get(sf)
        if sf in ("created_at", "updated_at", "last_interaction_at"):
            dt = _parse_dt(v) if isinstance(v, str) else None
            # put None at end consistently
            return (0, dt) if dt is not None else (1, datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))
        if sf == "full_name":
            return (0, (v or "").strip().lower())
        return (0, v)

    rev = (direction == "desc")
    matched.sort(key=_sort_key, reverse=rev)

    # Cursor: interpret as last seen contact id; start after it in current sort order
    start_idx = 0
    if cursor:
        idx = None
        for i, c in enumerate(matched):
            if isinstance(c, dict) and c.get("id") == cursor:
                idx = i
                break
        if idx is not None:
            start_idx = idx + 1

    page = matched[start_idx:start_idx + lim]
    has_more = start_idx + lim < len(matched)
    next_cursor = page[-1].get("id") if (has_more and page and isinstance(page[-1], dict)) else None

    # Optionally include notes (active only) per contact
    if include_notes:
        notes = _load("notes.json")
        if not isinstance(notes, list):
            notes = []
        notes_by_contact = {}
        for n in notes:
            if not isinstance(n, dict):
                continue
            if n.get("workspace_id") != ws_id or n.get("status") != "active":
                continue
            cid = n.get("contact_id")
            if isinstance(cid, str):
                notes_by_contact.setdefault(cid, []).append(n)
        # stable sort notes by created_at desc
        for cid, arr in notes_by_contact.items():
            arr.sort(key=lambda x: (_parse_dt(x.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
        out = []
        for c in page:
            if not isinstance(c, dict):
                continue
            cc = dict(c)
            cc["notes"] = notes_by_contact.get(c.get("id"), [])
            out.append(cc)
        page_out = out
    else:
        page_out = page

    resp = {"data": page_out, "total": len(matched), "has_more": has_more, "next_cursor": next_cursor}
    _log(ws_id, "ok", meta={"total": len(matched), "returned": len(page_out), "has_more": has_more})
    return resp

def searchInteractions(query=None, filters=None, sort=None, limit=None, cursor=None, include_contacts=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0361000" if __import__("os").path.isdir("./environment_mix/0361000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "searchInteractions"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _mk_req_id():
        return "clay_req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24].upper()

    def _log(workspace_id, status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _mk_req_id(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error"] = error
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(workspace_id):
        limits = _load("usage_limits.json")
        if not isinstance(limits, list):
            return None
        limit_row = None
        for r in limits:
            if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                limit_row = r
                break
        if not limit_row:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)

        def _ts(row):
            ts = row.get("timestamp")
            return _parse_dt(ts) if isinstance(ts, str) else None

        rl = limit_row.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl >= 0:
            win_start = now - datetime.timedelta(minutes=1)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= win_start:
                        used += 1
            if used >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", limit="per_minute", allowed=rl)

        quota = limit_row.get("monthly_quota")
        if isinstance(quota, int) and quota >= 0:
            month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= month_start:
                        used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Monthly quota exceeded for workspace.", quota=quota)
        return None

    # ---- validation ----
    if query is not None and not isinstance(query, str):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "query must be a string"})
        return _err("VALIDATION_ERROR", "query must be a string")
    if filters is not None and not isinstance(filters, dict):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "filters must be an object"})
        return _err("VALIDATION_ERROR", "filters must be an object")
    if sort is not None and not isinstance(sort, dict):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "sort must be an object"})
        return _err("VALIDATION_ERROR", "sort must be an object")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "limit must be an integer between 1 and 200"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "cursor must be a string"})
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if include_contacts is not None and not isinstance(include_contacts, bool):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "include_contacts must be a boolean"})
        return _err("VALIDATION_ERROR", "include_contacts must be a boolean")

    filters = filters or {}
    allowed_filter_keys = {
        "workspace_id", "status", "activity_type", "primary_contact_id", "group_id",
        "external_source", "external_id", "occurred_at", "start_at", "end_at", "relevance_score"
    }
    for k in filters.keys():
        if k not in allowed_filter_keys:
            _log(filters.get("workspace_id"), "error", error={"code": "VALIDATION_ERROR", "message": f"Unknown filter key: {k}"})
            return _err("VALIDATION_ERROR", f"Unknown filter key: {k}")

    ws_id = filters.get("workspace_id")
    if ws_id is not None and (not isinstance(ws_id, str) or not ws_id.strip()):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "filters.workspace_id must be a non-empty string"})
        return _err("VALIDATION_ERROR", "filters.workspace_id must be a non-empty string")

    activities = _load("activities.json")
    if not isinstance(activities, list):
        activities = []
    if ws_id is None:
        for a in activities:
            if isinstance(a, dict) and isinstance(a.get("workspace_id"), str) and a.get("workspace_id").strip():
                ws_id = a["workspace_id"]
                break
    if ws_id is None:
        _log(None, "error", error={"code": "UNAUTHORIZED", "message": "No authorized workspace can satisfy this request."})
        return _err("UNAUTHORIZED", "No authorized workspace can satisfy this request.")

    lim_err = _enforce_limits(ws_id)
    if lim_err:
        _log(ws_id, "error", error=lim_err["error"])
        return lim_err

    status_filter = filters.get("status")
    if status_filter is not None:
        if (not isinstance(status_filter, list)) or any((not isinstance(s, str) or s not in ("active", "cancelled", "deleted")) for s in status_filter):
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.status must be an array of valid statuses"})
            return _err("VALIDATION_ERROR", "filters.status must be an array of valid statuses")

    activity_type = filters.get("activity_type")
    if activity_type is not None:
        if (not isinstance(activity_type, list)) or any((not isinstance(s, str) or s not in ("meeting", "email", "call", "message", "note_reference", "other")) for s in activity_type):
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.activity_type must be an array of valid activity types"})
            return _err("VALIDATION_ERROR", "filters.activity_type must be an array of valid activity types")

    primary_contact_id = filters.get("primary_contact_id")
    if primary_contact_id is not None:
        if not isinstance(primary_contact_id, str) or re.match(r"^clay_ctc_[0-9A-Z]{18,}$", primary_contact_id) is None:
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.primary_contact_id does not match required pattern"})
            return _err("VALIDATION_ERROR", "filters.primary_contact_id does not match required pattern")

    group_id = filters.get("group_id")
    if group_id is not None:
        if not isinstance(group_id, str) or re.match(r"^clay_grp_[0-9A-Z]{18,}$", group_id) is None:
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.group_id does not match required pattern"})
            return _err("VALIDATION_ERROR", "filters.group_id does not match required pattern")

    external_source = filters.get("external_source")
    if external_source is not None and not isinstance(external_source, str):
        _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.external_source must be a string"})
        return _err("VALIDATION_ERROR", "filters.external_source must be a string")
    external_id = filters.get("external_id")
    if external_id is not None and not isinstance(external_id, str):
        _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.external_id must be a string"})
        return _err("VALIDATION_ERROR", "filters.external_id must be a string")

    def _validate_dt_range(obj, name):
        if obj is None:
            return (True, None, None)
        if not isinstance(obj, dict):
            return (False, None, None)
        for k in obj.keys():
            if k not in ("gte", "lte"):
                return (False, None, None)
        gte = obj.get("gte")
        lte = obj.get("lte")
        dgte = _parse_dt(gte) if gte is not None else None
        dlte = _parse_dt(lte) if lte is not None else None
        if (gte is not None and dgte is None) or (lte is not None and dlte is None):
            return (False, None, None)
        if dgte and dlte and dlte < dgte:
            return (False, None, None)
        return (True, dgte, dlte)

    for fld in ("occurred_at", "start_at", "end_at"):
        ok, _, _ = _validate_dt_range(filters.get(fld), fld)
        if not ok:
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": f"filters.{fld} must be a valid date-time range with gte<=lte"})
            return _err("VALIDATION_ERROR", f"filters.{fld} must be a valid date-time range with gte<=lte")

    rs = filters.get("relevance_score")
    if rs is not None:
        if not isinstance(rs, dict) or any(k not in ("gte", "lte") for k in rs.keys()):
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.relevance_score must be an object with gte/lte"})
            return _err("VALIDATION_ERROR", "filters.relevance_score must be an object with gte/lte")
        gte = rs.get("gte")
        lte = rs.get("lte")
        if gte is not None and not isinstance(gte, (int, float)):
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.relevance_score.gte must be a number"})
            return _err("VALIDATION_ERROR", "filters.relevance_score.gte must be a number")
        if lte is not None and not isinstance(lte, (int, float)):
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.relevance_score.lte must be a number"})
            return _err("VALIDATION_ERROR", "filters.relevance_score.lte must be a number")
        if gte is not None and lte is not None and lte < gte:
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.relevance_score must satisfy gte<=lte"})
            return _err("VALIDATION_ERROR", "filters.relevance_score must satisfy gte<=lte")

    if sort is None:
        sort = {"field": "occurred_at", "direction": "desc"}
    else:
        if set(sort.keys()) != {"field", "direction"}:
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "sort must include only field and direction"})
            return _err("VALIDATION_ERROR", "sort must include only field and direction")
        if sort["field"] not in ("occurred_at", "start_at", "created_at", "relevance_score"):
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "sort.field is invalid"})
            return _err("VALIDATION_ERROR", "sort.field is invalid")
        if sort["direction"] not in ("asc", "desc"):
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "sort.direction is invalid"})
            return _err("VALIDATION_ERROR", "sort.direction is invalid")

    lim = 50 if limit is None else limit
    q = (query or "").strip().lower()

    # group filter: only activities whose primary_contact_id is active member of group
    allowed_primary_ids = None
    if group_id is not None:
        groups = _load("groups.json")
        if not isinstance(groups, list):
            groups = []
        g = next((r for r in groups if isinstance(r, dict) and r.get("id") == group_id and r.get("workspace_id") == ws_id and r.get("status") != "deleted"), None)
        if g is None:
            _log(ws_id, "ok", meta={"total": 0})
            return {"data": [], "total": 0, "has_more": False, "next_cursor": None}
        memberships = _load("group_memberships.json")
        if not isinstance(memberships, list):
            memberships = []
        allowed_primary_ids = set()
        for m in memberships:
            if isinstance(m, dict) and m.get("workspace_id") == ws_id and m.get("group_id") == group_id and m.get("status") == "active":
                cid = m.get("contact_id")
                if isinstance(cid, str):
                    allowed_primary_ids.add(cid)

    contacts = _load("contacts.json")
    if not isinstance(contacts, list):
        contacts = []
    contacts_by_id = {c.get("id"): c for c in contacts if isinstance(c, dict) and c.get("workspace_id") == ws_id and c.get("status") != "deleted"}

    def _activity_text(a):
        parts = []
        for k in ("title", "body_preview", "external_source", "external_id", "location", "id", "activity_type"):
            v = a.get(k)
            if isinstance(v, str) and v:
                parts.append(v)
        for p in (a.get("participants") or []):
            if not isinstance(p, dict):
                continue
            for k in ("email", "name", "role", "contact_id"):
                v = p.get(k)
                if isinstance(v, str) and v:
                    parts.append(v)
        pcid = a.get("primary_contact_id")
        if isinstance(pcid, str):
            c = contacts_by_id.get(pcid)
            if isinstance(c, dict):
                for k in ("full_name", "company", "title", "email"):
                    v = c.get(k)
                    if isinstance(v, str) and v:
                        parts.append(v)
        return " ".join(parts).lower()

    def _match(a):
        if not isinstance(a, dict):
            return False
        if a.get("workspace_id") != ws_id:
            return False
        # never return deleted activities
        if a.get("status") == "deleted":
            return False
        if status_filter is not None:
            if a.get("status") not in status_filter:
                return False
            if a.get("status") == "deleted":
                return False
        else:
            if a.get("status") != "active":
                return False

        if activity_type is not None and a.get("activity_type") not in activity_type:
            return False
        if external_source is not None:
            if not isinstance(a.get("external_source"), str) or a.get("external_source") != external_source:
                return False
        if external_id is not None:
            if not isinstance(a.get("external_id"), str) or a.get("external_id") != external_id:
                return False

        pcid = a.get("primary_contact_id")
        if primary_contact_id is not None:
            if pcid != primary_contact_id:
                return False
        if allowed_primary_ids is not None:
            if not isinstance(pcid, str) or pcid not in allowed_primary_ids:
                return False

        # exclude if primary_contact_id refers to deleted/missing contact when include_contacts or filters require it
        if isinstance(pcid, str) and pcid not in contacts_by_id:
            # still allow activity without valid primary_contact_id unless group/primary filter depends on it
            if primary_contact_id is not None or allowed_primary_ids is not None or include_contacts:
                return False

        for fld in ("occurred_at", "start_at", "end_at"):
            rng = filters.get(fld)
            if rng is None:
                continue
            _, dgte, dlte = _validate_dt_range(rng, fld)
            cv = _parse_dt(a.get(fld)) if isinstance(a.get(fld), str) else None
            if cv is None:
                return False
            if dgte and cv < dgte:
                return False
            if dlte and cv > dlte:
                return False

        if rs is not None:
            val = a.get("relevance_score")
            if val is None or not isinstance(val, (int, float)):
                return False
            if rs.get("gte") is not None and val < rs["gte"]:
                return False
            if rs.get("lte") is not None and val > rs["lte"]:
                return False

        if q:
            return q in _activity_text(a)
        return True

    matched = [a for a in activities if _match(a)]

    sf = sort["field"]
    rev = (sort["direction"] == "desc")

    def _sort_key(a):
        v = a.get(sf)
        if sf in ("occurred_at", "start_at", "created_at"):
            dt = _parse_dt(v) if isinstance(v, str) else None
            return (0, dt) if dt is not None else (1, datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))
        if sf == "relevance_score":
            if isinstance(v, (int, float)):
                return (0, float(v))
            return (1, -1.0)
        return (0, v)

    matched.sort(key=_sort_key, reverse=rev)

    start_idx = 0
    if cursor:
        idx = None
        for i, a in enumerate(matched):
            if isinstance(a, dict) and a.get("id") == cursor:
                idx = i
                break
        if idx is not None:
            start_idx = idx + 1

    page = matched[start_idx:start_idx + lim]
    has_more = start_idx + lim < len(matched)
    next_cursor = page[-1].get("id") if (has_more and page and isinstance(page[-1], dict)) else None

    if include_contacts:
        out = []
        for a in page:
            if not isinstance(a, dict):
                continue
            aa = dict(a)
            pcid = aa.get("primary_contact_id")
            if isinstance(pcid, str) and pcid in contacts_by_id:
                aa["primary_contact"] = contacts_by_id[pcid]
            else:
                aa["primary_contact"] = None
            out.append(aa)
        page_out = out
    else:
        page_out = page

    resp = {"data": page_out, "total": len(matched), "has_more": has_more, "next_cursor": next_cursor}
    _log(ws_id, "ok", meta={"total": len(matched), "returned": len(page_out), "has_more": has_more})
    return resp

def aggregateContacts(query=None, filters=None, metric=None, group_by=None, limit=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0361000" if __import__("os").path.isdir("./environment_mix/0361000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "aggregateContacts"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _mk_req_id():
        return "clay_req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24].upper()

    def _log(workspace_id, status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _mk_req_id(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error"] = error
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(workspace_id):
        limits = _load("usage_limits.json")
        if not isinstance(limits, list):
            return None
        limit_row = None
        for r in limits:
            if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                limit_row = r
                break
        if not limit_row:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)

        def _ts(row):
            ts = row.get("timestamp")
            return _parse_dt(ts) if isinstance(ts, str) else None

        rl = limit_row.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl >= 0:
            win_start = now - datetime.timedelta(minutes=1)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= win_start:
                        used += 1
            if used >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", limit="per_minute", allowed=rl)

        quota = limit_row.get("monthly_quota")
        if isinstance(quota, int) and quota >= 0:
            month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= month_start:
                        used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Monthly quota exceeded for workspace.", quota=quota)
        return None

    # ---- validation ----
    if metric is None or not isinstance(metric, str) or metric not in ("count",):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "metric is required and must be 'count'"})
        return _err("VALIDATION_ERROR", "metric is required and must be 'count'")

    if query is not None and not isinstance(query, str):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "query must be a string"})
        return _err("VALIDATION_ERROR", "query must be a string")

    if filters is not None and not isinstance(filters, dict):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "filters must be an object"})
        return _err("VALIDATION_ERROR", "filters must be an object")

    if group_by is not None and (not isinstance(group_by, str) or group_by not in ("company", "company_domain", "title", "location", "status", "source")):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "group_by is invalid"})
        return _err("VALIDATION_ERROR", "group_by is invalid")

    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        _log(filters.get("workspace_id") if isinstance(filters, dict) else None, "error",
             error={"code": "VALIDATION_ERROR", "message": "limit must be an integer between 1 and 200"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    filters = filters or {}
    allowed_filter_keys = {"status", "workspace_id", "group_id", "company", "company_domain", "title", "location", "created_at", "last_interaction_at"}
    for k in filters.keys():
        if k not in allowed_filter_keys:
            _log(filters.get("workspace_id"), "error", error={"code": "VALIDATION_ERROR", "message": f"Unknown filter key: {k}"})
            return _err("VALIDATION_ERROR", f"Unknown filter key: {k}")

    ws_id = filters.get("workspace_id")
    if ws_id is not None and (not isinstance(ws_id, str) or not ws_id.strip()):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "filters.workspace_id must be a non-empty string"})
        return _err("VALIDATION_ERROR", "filters.workspace_id must be a non-empty string")

    contacts = _load("contacts.json")
    if not isinstance(contacts, list):
        contacts = []
    if ws_id is None:
        for c in contacts:
            if isinstance(c, dict) and isinstance(c.get("workspace_id"), str) and c.get("workspace_id").strip():
                ws_id = c["workspace_id"]
                break
    if ws_id is None:
        _log(None, "error", error={"code": "UNAUTHORIZED", "message": "No authorized workspace can satisfy this request."})
        return _err("UNAUTHORIZED", "No authorized workspace can satisfy this request.")

    lim_err = _enforce_limits(ws_id)
    if lim_err:
        _log(ws_id, "error", error=lim_err["error"])
        return lim_err

    status_filter = filters.get("status")
    if status_filter is not None:
        if not isinstance(status_filter, list) or any((not isinstance(s, str) or s not in ("active", "archived", "deleted")) for s in status_filter):
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.status must be an array of valid statuses"})
            return _err("VALIDATION_ERROR", "filters.status must be an array of valid statuses")

    group_id = filters.get("group_id")
    if group_id is not None:
        if not isinstance(group_id, str) or re.match(r"^clay_grp_[0-9A-Z]{18,}$", group_id) is None:
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "filters.group_id does not match required pattern"})
            return _err("VALIDATION_ERROR", "filters.group_id does not match required pattern")

    def _validate_dt_range(obj, name):
        if obj is None:
            return (True, None, None)
        if not isinstance(obj, dict):
            return (False, None, None)
        for k in obj.keys():
            if k not in ("gte", "lte"):
                return (False, None, None)
        gte = obj.get("gte")
        lte = obj.get("lte")
        dgte = _parse_dt(gte) if gte is not None else None
        dlte = _parse_dt(lte) if lte is not None else None
        if (gte is not None and dgte is None) or (lte is not None and dlte is None):
            return (False, None, None)
        if dgte and dlte and dlte < dgte:
            return (False, None, None)
        return (True, dgte, dlte)

    for fld in ("created_at", "last_interaction_at"):
        ok, _, _ = _validate_dt_range(filters.get(fld), fld)
        if not ok:
            _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": f"filters.{fld} must be a valid date-time range with gte<=lte"})
            return _err("VALIDATION_ERROR", f"filters.{fld} must be a valid date-time range with gte<=lte")

    # group membership scope (active members only)
    active_member_ids = None
    if group_id is not None:
        groups = _load("groups.json")
        if not isinstance(groups, list):
            groups = []
        g = next((r for r in groups if isinstance(r, dict) and r.get("id") == group_id and r.get("workspace_id") == ws_id and r.get("status") != "deleted"), None)
        if g is None:
            # no matches, return empty aggregates (not error)
            out = {"metric": metric, "group_by": group_by, "total_matched": 0}
            if group_by:
                out["buckets"] = []
            else:
                out["value"] = 0
            _log(ws_id, "ok", meta={"total_matched": 0})
            return out

        memberships = _load("group_memberships.json")
        if not isinstance(memberships, list):
            memberships = []
        active_member_ids = set()
        for m in memberships:
            if not isinstance(m, dict):
                continue
            if m.get("workspace_id") != ws_id:
                continue
            if m.get("group_id") == group_id and m.get("status") == "active":
                cid = m.get("contact_id")
                if isinstance(cid, str):
                    active_member_ids.add(cid)

    q = (query or "").strip().lower()

    def _text_blob(c):
        parts = []
        for k in ("full_name", "first_name", "last_name", "title", "company", "company_domain", "location", "id"):
            v = c.get(k)
            if isinstance(v, str) and v:
                parts.append(v)
        for e in (c.get("emails") or []):
            if isinstance(e, dict):
                v = e.get("value")
                if isinstance(v, str) and v:
                    parts.append(v)
            elif isinstance(e, str):
                parts.append(e)
        return " ".join(parts).lower()

    def _match(c):
        if not isinstance(c, dict):
            return False
        if c.get("workspace_id") != ws_id:
            return False
        # business rule: aggregation should not include deleted contacts by default
        if c.get("status") == "deleted":
            return False
        if status_filter is not None:
            if c.get("status") not in status_filter:
                return False
            if c.get("status") == "deleted":
                return False
        else:
            if c.get("status") not in ("active", "archived"):
                return False
        if active_member_ids is not None and c.get("id") not in active_member_ids:
            return False

        def _submatch(field, val, exact=False):
            if val is None:
                return True
            if not isinstance(val, str):
                return False
            cv = c.get(field)
            if not isinstance(cv, str):
                return False
            if exact:
                return cv.strip().lower() == val.strip().lower()
            return val.strip().lower() in cv.strip().lower()

        if not _submatch("company", filters.get("company"), exact=False):
            return False
        if not _submatch("company_domain", filters.get("company_domain"), exact=True):
            return False
        if not _submatch("title", filters.get("title"), exact=False):
            return False
        if not _submatch("location", filters.get("location"), exact=False):
            return False

        for fld in ("created_at", "last_interaction_at"):
            rng = filters.get(fld)
            if rng is None:
                continue
            _, dgte, dlte = _validate_dt_range(rng, fld)
            cv = _parse_dt(c.get(fld)) if isinstance(c.get(fld), str) else None
            if cv is None:
                return False
            if dgte and cv < dgte:
                return False
            if dlte and cv > dlte:
                return False

        if q:
            return q in _text_blob(c)
        return True

    matched = [c for c in contacts if _match(c)]
    total = len(matched)

    if group_by:
        buckets = {}
        for c in matched:
            v = c.get(group_by)
            key = ""
            if isinstance(v, str):
                key = v.strip()
            elif v is None:
                key = ""
            else:
                key = str(v)
            buckets[key] = buckets.get(key, 0) + 1
        # sort by count desc then key asc, limit applies
        items = [{"key": k, "count": v} for k, v in buckets.items()]
        items.sort(key=lambda x: (-x["count"], (x["key"] or "").lower()))
        if limit is not None:
            items = items[:limit]
        resp = {"metric": metric, "group_by": group_by, "total_matched": total, "buckets": items}
        _log(ws_id, "ok", meta={"total_matched": total, "buckets": len(items)})
        return resp

    resp = {"metric": metric, "total_matched": total, "value": total}
    _log(ws_id, "ok", meta={"total_matched": total})
    return resp

def getContact(contact_id, include_notes=None, notes_limit=None, notes_cursor=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0361000" if __import__("os").path.isdir("./environment_mix/0361000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getContact"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _mk_req_id():
        return "clay_req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24].upper()

    def _log(workspace_id, status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _mk_req_id(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error"] = error
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(workspace_id):
        limits = _load("usage_limits.json")
        if not isinstance(limits, list):
            return None
        limit_row = None
        for r in limits:
            if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                limit_row = r
                break
        if not limit_row:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)

        def _ts(row):
            ts = row.get("timestamp")
            return _parse_dt(ts) if isinstance(ts, str) else None

        rl = limit_row.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl >= 0:
            win_start = now - datetime.timedelta(minutes=1)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= win_start:
                        used += 1
            if used >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", limit="per_minute", allowed=rl)

        quota = limit_row.get("monthly_quota")
        if isinstance(quota, int) and quota >= 0:
            month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= month_start:
                        used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Monthly quota exceeded for workspace.", quota=quota)
        return None

    # validation
    if not isinstance(contact_id, str) or not contact_id.strip():
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "contact_id is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "contact_id is required and must be a non-empty string")
    if re.match(r"^clay_ctc_[0-9A-Z]{18,}$", contact_id) is None:
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "contact_id does not match required pattern"})
        return _err("VALIDATION_ERROR", "contact_id does not match required pattern")
    if include_notes is not None and not isinstance(include_notes, bool):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "include_notes must be a boolean"})
        return _err("VALIDATION_ERROR", "include_notes must be a boolean")
    if notes_limit is not None and (not isinstance(notes_limit, int) or notes_limit < 1 or notes_limit > 200):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "notes_limit must be an integer between 1 and 200"})
        return _err("VALIDATION_ERROR", "notes_limit must be an integer between 1 and 200")
    if notes_cursor is not None and not isinstance(notes_cursor, str):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "notes_cursor must be a string"})
        return _err("VALIDATION_ERROR", "notes_cursor must be a string")

    contacts = _load("contacts.json")
    if not isinstance(contacts, list):
        contacts = []

    contact = next((c for c in contacts if isinstance(c, dict) and c.get("id") == contact_id), None)
    if contact is None or contact.get("status") == "deleted":
        _log(contact.get("workspace_id") if isinstance(contact, dict) else None, "error",
             error={"code": "NOT_FOUND", "message": "Contact not found"})
        return _err("NOT_FOUND", "Contact not found")

    ws_id = contact.get("workspace_id") if isinstance(contact.get("workspace_id"), str) else None
    if ws_id is None:
        _log(None, "error", error={"code": "UNAUTHORIZED", "message": "No authorized workspace can satisfy this request."})
        return _err("UNAUTHORIZED", "No authorized workspace can satisfy this request.")

    lim_err = _enforce_limits(ws_id)
    if lim_err:
        _log(ws_id, "error", error=lim_err["error"])
        return lim_err

    resp_contact = dict(contact)
    # ensure arrays exist
    for k in ("emails", "phones", "social_links"):
        if not isinstance(resp_contact.get(k), list):
            resp_contact[k] = []

    if include_notes:
        notes = _load("notes.json")
        if not isinstance(notes, list):
            notes = []
        # only active notes for this contact in same workspace
        matched_notes = [n for n in notes if isinstance(n, dict) and n.get("workspace_id") == ws_id and n.get("contact_id") == contact_id and n.get("status") == "active"]
        matched_notes.sort(key=lambda x: (_parse_dt(x.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)

        lim = 50 if notes_limit is None else notes_limit
        start_idx = 0
        if notes_cursor:
            idx = None
            for i, n in enumerate(matched_notes):
                if isinstance(n, dict) and n.get("id") == notes_cursor:
                    idx = i
                    break
            if idx is not None:
                start_idx = idx + 1
        page = matched_notes[start_idx:start_idx + lim]
        has_more = start_idx + lim < len(matched_notes)
        next_cursor = page[-1].get("id") if (has_more and page and isinstance(page[-1], dict)) else None
        resp_contact["notes"] = {"data": page, "total": len(matched_notes), "has_more": has_more, "next_cursor": next_cursor}

    _log(ws_id, "ok", meta={"include_notes": bool(include_notes)})
    return {"data": resp_contact}

def createContact(workspace_id, first_name=None, last_name=None, full_name=None, title=None, company=None, company_domain=None, location=None, emails=None, phones=None, social_links=None, source=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0361000" if __import__("os").path.isdir("./environment_mix/0361000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "createContact"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _mk_req_id():
        import hashlib
        return "clay_req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24].upper()

    def _log(ws_id, status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _mk_req_id(),
            "endpoint": endpoint,
            "workspace_id": ws_id,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error"] = error
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # validation
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "workspace_id is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "workspace_id is required and must be a non-empty string")

    for fname, val in [
        ("first_name", first_name), ("last_name", last_name), ("full_name", full_name),
        ("title", title), ("company", company), ("company_domain", company_domain),
        ("location", location), ("source", source)
    ]:
        if val is not None and not isinstance(val, str):
            _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": f"{fname} must be a string"})
            return _err("VALIDATION_ERROR", f"{fname} must be a string")

    if emails is not None and not isinstance(emails, list):
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "emails must be an array of strings"})
        return _err("VALIDATION_ERROR", "emails must be an array of strings")
    if phones is not None and not isinstance(phones, list):
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "phones must be an array of strings"})
        return _err("VALIDATION_ERROR", "phones must be an array of strings")
    if social_links is not None and not isinstance(social_links, list):
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "social_links must be an array of strings"})
        return _err("VALIDATION_ERROR", "social_links must be an array of strings")

    email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
    def _clean_str(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = " ".join(s.strip().split())
        return s2 if s2 else None

    def _emails_obj(lst):
        out = []
        if not lst:
            return out
        for i, e in enumerate(lst):
            if not isinstance(e, str):
                return None
            v = e.strip()
            if not email_re.match(v):
                return None
            out.append({"value": v, "label": None, "primary": True if i == 0 else False})
        # ensure only one primary
        if out:
            for j in range(1, len(out)):
                out[j]["primary"] = False
        return out

    def _phones_obj(lst):
        out = []
        if not lst:
            return out
        for i, p in enumerate(lst):
            if not isinstance(p, str):
                return None
            v = p.strip()
            if len(v) < 6 or len(v) > 32:
                return None
            out.append({"value": v, "label": None, "primary": True if i == 0 else False})
        if out:
            for j in range(1, len(out)):
                out[j]["primary"] = False
        return out

    def _social_obj(lst):
        out = []
        if not lst:
            return out
        for s in lst:
            if not isinstance(s, str):
                return None
            u = s.strip()
            if not u:
                continue
            # type is unknown; store as "other"
            out.append({"type": "other", "url": u})
        return out

    emails_obj = _emails_obj(emails)
    if emails_obj is None:
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "each emails[] value must be a valid email format"})
        return _err("VALIDATION_ERROR", "each emails[] value must be a valid email format")
    phones_obj = _phones_obj(phones)
    if phones_obj is None:
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "each phones[] value length must be between 6 and 32 characters"})
        return _err("VALIDATION_ERROR", "each phones[] value length must be between 6 and 32 characters")
    social_obj = _social_obj(social_links)
    if social_obj is None:
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "social_links must be an array of strings"})
        return _err("VALIDATION_ERROR", "social_links must be an array of strings")

    fn = _clean_str(first_name)
    ln = _clean_str(last_name)
    full = _clean_str(full_name)
    if full is None:
        if fn or ln:
            full = " ".join([x for x in [fn, ln] if x])
        else:
            full = None

    title = _clean_str(title)
    company = _clean_str(company)
    company_domain = _clean_str(company_domain)
    location = _clean_str(location)
    source = _clean_str(source)

    contacts = _load("contacts.json")
    if not isinstance(contacts, list):
        contacts = []

    # best-effort de-dupe: unique(workspace_id, lower(full_name), lower(company)) where status != deleted
    ignore_dedupe = bool(_extra.get("ignore_duplicate_check") or _extra.get("ignore_dedupe") or _extra.get("internal_ignore_duplicate_check"))
    if not ignore_dedupe and full and company:
        full_l = full.strip().lower()
        comp_l = company.strip().lower()
        for c in contacts:
            if not isinstance(c, dict):
                continue
            if c.get("workspace_id") != workspace_id:
                continue
            if c.get("status") == "deleted":
                continue
            if isinstance(c.get("full_name"), str) and isinstance(c.get("company"), str):
                if c["full_name"].strip().lower() == full_l and c["company"].strip().lower() == comp_l:
                    # real rule says reject or warn; we reject with conflict
                    _log(workspace_id, "error", error={"code": "CONFLICT", "message": "Duplicate contact (same full_name + company) exists in workspace.", "existing_contact_id": c.get("id")})
                    return _err("CONFLICT", "Duplicate contact (same full_name + company) exists in workspace.", existing_contact_id=c.get("id"))

    existing_ids = {c.get("id") for c in contacts if isinstance(c, dict)}
    def _new_contact_id():
        # similar to dataset: clay_ctc_ + 24 chars
        for _ in range(200):
            cand = "clay_ctc_" + secrets.token_hex(12).upper()
            if cand not in existing_ids:
                return cand
        return "clay_ctc_" + secrets.token_hex(12).upper()

    now = _now_iso()
    new_row = {
        "id": _new_contact_id(),
        "workspace_id": workspace_id,
        "status": "active",
        "first_name": fn,
        "last_name": ln,
        "full_name": full,
        "title": title,
        "company": company,
        "company_domain": company_domain,
        "location": location,
        "emails": emails_obj if emails_obj is not None else [],
        "phones": phones_obj if phones_obj is not None else [],
        "social_links": social_obj if social_obj is not None else [],
        "source": source,
        "created_at": now,
        "updated_at": now,
        "last_interaction_at": None
    }

    contacts.append(new_row)
    _save("contacts.json", contacts)
    _log(workspace_id, "ok", meta={"created_contact_id": new_row["id"]})
    return {"data": new_row}

def createNote(workspace_id, contact_id, content, created_by=None, **_extra):
    import json, os, datetime, time, re, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0361000" if __import__("os").path.isdir("./environment_mix/0361000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "createNote"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _mk_req_id():
        return "clay_req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24].upper()

    def _log(ws_id, status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _mk_req_id(),
            "endpoint": endpoint,
            "workspace_id": ws_id,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error"] = error
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(workspace_id):
        limits = _load("usage_limits.json")
        if not isinstance(limits, list):
            return None
        limit_row = None
        for r in limits:
            if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                limit_row = r
                break
        if not limit_row:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)

        def _parse_dt(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        def _ts(row):
            ts = row.get("timestamp")
            return _parse_dt(ts) if isinstance(ts, str) else None

        rl = limit_row.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl >= 0:
            win_start = now - datetime.timedelta(minutes=1)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= win_start:
                        used += 1
            if used >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", limit="per_minute", allowed=rl)

        quota = limit_row.get("monthly_quota")
        if isinstance(quota, int) and quota >= 0:
            month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= month_start:
                        used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Monthly quota exceeded for workspace.", quota=quota)
        return None

    # validate inputs
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "workspace_id is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "workspace_id is required and must be a non-empty string")
    if not isinstance(contact_id, str) or re.match(r"^clay_ctc_[0-9A-Z]{18,}$", contact_id) is None:
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "contact_id does not match required pattern"})
        return _err("VALIDATION_ERROR", "contact_id does not match required pattern")
    if not isinstance(content, str):
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "content must be a string"})
        return _err("VALIDATION_ERROR", "content must be a string")
    content_str = content
    if len(content_str) < 1 or len(content_str) > 20000:
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "content length must be between 1 and 20000 characters"})
        return _err("VALIDATION_ERROR", "content length must be between 1 and 20000 characters")
    if created_by is not None and not isinstance(created_by, str):
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "created_by must be a string"})
        return _err("VALIDATION_ERROR", "created_by must be a string")

    lim_err = _enforce_limits(workspace_id)
    if lim_err:
        _log(workspace_id, "error", error=lim_err["error"])
        return lim_err

    # validate FK and workspace scope
    contacts = _load("contacts.json")
    if not isinstance(contacts, list):
        contacts = []
    c = next((r for r in contacts if isinstance(r, dict) and r.get("id") == contact_id), None)
    if c is None or c.get("status") == "deleted":
        _log(workspace_id, "error", error={"code": "NOT_FOUND", "message": "Contact not found"})
        return _err("NOT_FOUND", "Contact not found")
    if c.get("workspace_id") != workspace_id:
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "workspace_id must match contact.workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id must match contact.workspace_id")

    notes = _load("notes.json")
    if not isinstance(notes, list):
        notes = []
    existing_ids = {n.get("id") for n in notes if isinstance(n, dict)}
    def _new_note_id():
        for _ in range(200):
            cand = "clay_note_" + secrets.token_hex(12).upper()
            if cand not in existing_ids:
                return cand
        return "clay_note_" + secrets.token_hex(12).upper()

    now = _now_iso()
    row = {
        "id": _new_note_id(),
        "workspace_id": workspace_id,
        "contact_id": contact_id,
        "status": "active",
        "content": content_str,
        "created_by": created_by,
        "created_at": now,
        "updated_at": now
    }
    notes.append(row)
    _save("notes.json", notes)
    _log(workspace_id, "ok", meta={"created_note_id": row["id"], "contact_id": contact_id})
    return {"data": row}

