            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)

        def _ts(row):
            ts = row.get("timestamp")
            return _parse_dt(ts) if isinstance(ts, str) else None

        rl = limit_row.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl >= 0:
            win_start = now - datetime.timedelta(minutes=1)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= win_start:
                        used += 1
            if used >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", limit="per_minute", allowed=rl)

        quota = limit_row.get("monthly_quota")
        if isinstance(quota, int) and quota >= 0:
            month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= month_start:
                        used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Monthly quota exceeded for workspace.", quota=quota)
        return None

    # validation
    if workspace_id is not None and (not isinstance(workspace_id, str) or not workspace_id.strip()):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "workspace_id must be a non-empty string when provided"})
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string when provided")
    if status is not None:
        if not isinstance(status, list) or any((not isinstance(s, str) or s not in ("active", "archived", "deleted")) for s in status):
            _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "status must be an array of valid statuses"})
            return _err("VALIDATION_ERROR", "status must be an array of valid statuses")
    if query is not None and not isinstance(query, str):
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "query must be a string"})
        return _err("VALIDATION_ERROR", "query must be a string")
    if sort is not None:
        if not isinstance(sort, dict) or set(sort.keys()) != {"field", "direction"}:
            _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "sort must be an object with field and direction"})
            return _err("VALIDATION_ERROR", "sort must be an object with field and direction")
        if sort["field"] not in ("name", "created_at", "updated_at", "member_count_cached"):
            _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "sort.field is invalid"})
            return _err("VALIDATION_ERROR", "sort.field is invalid")
        if sort["direction"] not in ("asc", "desc"):
            _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "sort.direction is invalid"})
            return _err("VALIDATION_ERROR", "sort.direction is invalid")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "limit must be an integer between 1 and 200"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log(workspace_id, "error", error={"code": "VALIDATION_ERROR", "message": "cursor must be a string"})
        return _err("VALIDATION_ERROR", "cursor must be a string")

    groups = _load("groups.json")
    if not isinstance(groups, list):
        groups = []

    # ambient auth: choose workspace from groups if none provided
    ws_id = workspace_id
    if ws_id is None:
        for g in groups:
            if isinstance(g, dict) and isinstance(g.get("workspace_id"), str) and g.get("workspace_id").strip():
                ws_id = g["workspace_id"]
                break
    if ws_id is None:
        _log(None, "error", error={"code": "UNAUTHORIZED", "message": "No authorized workspace can satisfy this request."})
        return _err("UNAUTHORIZED", "No authorized workspace can satisfy this request.")

    lim_err = _enforce_limits(ws_id)
    if lim_err:
        _log(ws_id, "error", error=lim_err["error"])
        return lim_err

    q = (query or "").strip().lower()

    def _match(g):
        if not isinstance(g, dict):
            return False
        if g.get("workspace_id") != ws_id:
            return False
        # business rule: never include deleted groups
        if g.get("status") == "deleted":
            return False
        if status is not None:
            if g.get("status") not in status:
                return False
            if g.get("status") == "deleted":
                return False
        else:
            if g.get("status") not in ("active", "archived"):
                return False
        if q:
            name = g.get("name") if isinstance(g.get("name"), str) else ""
            desc = g.get("description") if isinstance(g.get("description"), str) else ""
            blob = (name + " " + desc).lower()
            return q in blob
        return True

    matched = [g for g in groups if _match(g)]

    if sort is None:
        sort = {"field": "name", "direction": "asc"}
    sf = sort["field"]
    rev = (sort["direction"] == "desc")

    def _sort_key(g):
        v = g.get(sf)
        if sf in ("created_at", "updated_at"):
            dt = _parse_dt(v) if isinstance(v, str) else None
            return (0, dt) if dt else (1, datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))
        if sf == "member_count_cached":
            return (0, int(v)) if isinstance(v, int) else (1, -1)
        if sf == "name":
            return (0, (v or "").strip().lower())
        return (0, v)

    matched.sort(key=_sort_key, reverse=rev)

    lim = 50 if limit is None else limit
    start_idx = 0
    if cursor:
        idx = None
        for i, g in enumerate(matched):
            if isinstance(g, dict) and g.get("id") == cursor:
                idx = i
                break
        if idx is not None:
            start_idx = idx + 1

    page = matched[start_idx:start_idx + lim]
    has_more = start_idx + lim < len(matched)
    next_cursor = page[-1].get("id") if (has_more and page and isinstance(page[-1], dict)) else None

    resp = {"data": page, "total": len(matched), "has_more": has_more, "next_cursor": next_cursor}
    _log(ws_id, "ok", meta={"total": len(matched), "returned": len(page), "has_more": has_more})
    return resp

