def updateGroup(group_id, name=None, description=None, status=None, add_contact_ids=None, remove_contact_ids=None, **_extra):
    import json, os, datetime, re, time, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0361000" if __import__("os").path.isdir("./environment_mix/0361000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updateGroup"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _mk_req_id():
        return "clay_req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24].upper()

    def _log(ws_id, status_s, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _mk_req_id(),
            "endpoint": endpoint,
            "workspace_id": ws_id,
            "status": status_s,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error"] = error
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(workspace_id):
        limits = _load("usage_limits.json")
        if not isinstance(limits, list):
            return None
        limit_row = None
        for r in limits:
            if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                limit_row = r
                break
        if not limit_row:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)

        def _ts(row):
            ts = row.get("timestamp")
            return _parse_dt(ts) if isinstance(ts, str) else None

        rl = limit_row.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl >= 0:
            win_start = now - datetime.timedelta(minutes=1)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= win_start:
                        used += 1
            if used >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", limit="per_minute", allowed=rl)

        quota = limit_row.get("monthly_quota")
        if isinstance(quota, int) and quota >= 0:
            month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            used = 0
            for r in logs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                    dt = _ts(r)
                    if dt and dt >= month_start:
                        used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Monthly quota exceeded for workspace.", quota=quota)
        return None

    # validation
    if not isinstance(group_id, str) or not group_id.strip():
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "group_id is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "group_id is required and must be a non-empty string")
    if re.match(r"^clay_grp_[A-Za-z0-9]+$", group_id) is None:
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "group_id does not match required pattern"})
        return _err("VALIDATION_ERROR", "group_id does not match required pattern")
    if name is not None and not isinstance(name, str):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "name must be a string"})
        return _err("VALIDATION_ERROR", "name must be a string")
    if description is not None and not isinstance(description, str):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "description must be a string"})
        return _err("VALIDATION_ERROR", "description must be a string")
    if status is not None and (not isinstance(status, str) or status not in ("active", "archived", "deleted")):
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "status must be one of active, archived, deleted"})
        return _err("VALIDATION_ERROR", "status must be one of active, archived, deleted")

    def _validate_contact_ids(arr, field):
        if arr is None:
            return []
        if not isinstance(arr, list):
            return None
        out = []
        for cid in arr:
            if not isinstance(cid, str) or re.match(r"^clay_ctc_[A-Za-z0-9]+$", cid) is None:
                return None
            out.append(cid)
        # dedupe while preserving order
        seen = set()
        dedup = []
        for cid in out:
            if cid not in seen:
                seen.add(cid)
                dedup.append(cid)
        return dedup

    add_ids = _validate_contact_ids(add_contact_ids, "add_contact_ids")
    if add_ids is None:
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "add_contact_ids must be an array of valid contact ids"})
        return _err("VALIDATION_ERROR", "add_contact_ids must be an array of valid contact ids")
    rem_ids = _validate_contact_ids(remove_contact_ids, "remove_contact_ids")
    if rem_ids is None:
        _log(None, "error", error={"code": "VALIDATION_ERROR", "message": "remove_contact_ids must be an array of valid contact ids"})
        return _err("VALIDATION_ERROR", "remove_contact_ids must be an array of valid contact ids")

    groups = _load("groups.json")
    if not isinstance(groups, list):
        groups = []
    idx = None
    group = None
    for i, g in enumerate(groups):
        if isinstance(g, dict) and g.get("id") == group_id:
            idx = i
            group = g
            break
    if group is None or group.get("status") == "deleted":
        _log(group.get("workspace_id") if isinstance(group, dict) else None, "error", error={"code": "NOT_FOUND", "message": "Group not found"})
        return _err("NOT_FOUND", "Group not found")

    ws_id = group.get("workspace_id") if isinstance(group.get("workspace_id"), str) else None
    if ws_id is None:
        _log(None, "error", error={"code": "UNAUTHORIZED", "message": "No authorized workspace can satisfy this request."})
        return _err("UNAUTHORIZED", "No authorized workspace can satisfy this request.")

    lim_err = _enforce_limits(ws_id)
    if lim_err:
        _log(ws_id, "error", error=lim_err["error"])
        return lim_err

    # apply lifecycle transition for group status
    transitions = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
    if status is not None and status != group.get("status"):
        cur = group.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _log(ws_id, "error", error={"code": "INVALID_TRANSITION", "message": f"Illegal status transition {cur} -> {status}"})
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}")

    # pre-load contacts and memberships for FK validation and idempotent bulk application
    contacts = _load("contacts.json")
    if not isinstance(contacts, list):
        contacts = []
    contacts_by_id = {c.get("id"): c for c in contacts if isinstance(c, dict)}

    memberships = _load("group_memberships.json")
    if not isinstance(memberships, list):
        memberships = []

    # membership index by (group_id, contact_id)
    mem_index = {}
    for j, m in enumerate(memberships):
        if isinstance(m, dict) and m.get("group_id") == group_id and isinstance(m.get("contact_id"), str):
            mem_index[(group_id, m["contact_id"])] = (j, m)

    existing_mem_ids = {m.get("id") for m in memberships if isinstance(m, dict)}
    def _new_mem_id():
        for _ in range(200):
            cand = "clay_gm_" + secrets.token_hex(12).upper()
            if cand not in existing_mem_ids:
                return cand
        return "clay_gm_" + secrets.token_hex(12).upper()

    now = _now_iso()
    changed = False
    membership_changed = False

    # group field updates
    if name is not None:
        group["name"] = " ".join(name.strip().split())
        changed = True
    if description is not None:
        group["description"] = description
        changed = True
    if status is not None and status != group.get("status"):
        group["status"] = status
        changed = True

    # bulk membership changes (single "transaction" in-memory then save)
    # Validate FK: contact exists, not deleted, same workspace
    def _validate_contact_for_membership(cid):
        c = contacts_by_id.get(cid)
        if not isinstance(c, dict):
            return (False, "NOT_FOUND", "Contact not found")
        if c.get("status") == "deleted":
            return (False, "NOT_FOUND", "Contact not found")
        if c.get("workspace_id") != ws_id:
            return (False, "VALIDATION_ERROR", "Cross-workspace foreign key: contact_id belongs to different workspace")
        return (True, None, None)

    # Apply removals then adds (idempotent)
    for cid in rem_ids:
        ok, code, msg = _validate_contact_for_membership(cid)
        if not ok and code == "VALIDATION_ERROR":
            _log(ws_id, "error", error={"code": code, "message": msg})
            return _err(code, msg)
        # removing missing is no-op
        key = (group_id, cid)
        if key in mem_index:
            j, m = mem_index[key]
            if m.get("workspace_id") != ws_id:
                _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "Cross-workspace membership row"})
                return _err("VALIDATION_ERROR", "Cross-workspace membership row")
            if m.get("status") != "removed":
                m["status"] = "removed"
                m["removed_at"] = now
                m["updated_at"] = now
                membership_changed = True
        # else: no-op

    for cid in add_ids:
        ok, code, msg = _validate_contact_for_membership(cid)
        if not ok:
            _log(ws_id, "error", error={"code": code, "message": msg})
            return _err(code, msg)
        key = (group_id, cid)
        if key in mem_index:
            j, m = mem_index[key]
            if m.get("workspace_id") != ws_id:
                _log(ws_id, "error", error={"code": "VALIDATION_ERROR", "message": "Cross-workspace membership row"})
                return _err("VALIDATION_ERROR", "Cross-workspace membership row")
            # idempotent: adding existing active is no-op; if removed, reactivate
            if m.get("status") != "active":
                m["status"] = "active"
                m["removed_at"] = None
                m["added_at"] = m.get("added_at") or now
                m["updated_at"] = now
                membership_changed = True
        else:
            row = {
                "id": _new_mem_id(),
                "workspace_id": ws_id,
                "group_id": group_id,
                "contact_id": cid,
                "status": "active",
                "added_at": now,
                "removed_at": None,
                "created_at": now,
                "updated_at": now
            }
            memberships.append(row)
            mem_index[key] = (len(memberships) - 1, row)
            membership_changed = True

    # maintain cached member count when memberships change (or group status changes)
    if membership_changed or (status is not None):
        active_count = 0
        for m in memberships:
            if not isinstance(m, dict):
                continue
            if m.get("workspace_id") != ws_id:
                continue
            if m.get("group_id") == group_id and m.get("status") == "active":
                active_count += 1
        group["member_count_cached"] = active_count
        changed = True

    if changed:
        group["updated_at"] = now
        groups[idx] = group
        _save("groups.json", groups)
    if membership_changed:
        _save("group_memberships.json", memberships)

    if not changed and not membership_changed:
        # nothing to do: but request matched a row; return current group (idempotent)
        _log(ws_id, "ok", meta={"updated": False, "membership_changed": False})
        return {"data": group, "updated": False}

    _log(ws_id, "ok", meta={"updated": True, "membership_changed": membership_changed, "member_count_cached": group.get("member_count_cached")})
    return {"data": group, "updated": True, "membership_changed": membership_changed}

def getNotes(start_date, end_date, contact_id=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0361000" if __import__("os").path.isdir("./environment_mix/0361000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _new_id(prefix, rows):
        import secrets
        existing = set(r.get("id") for r in rows if isinstance(r, dict))
        for _ in range(50):
            cand = f"{prefix}{secrets.token_urlsafe(9).replace('-', '').replace('_', '')[:12]}"
            if cand not in existing:
                return cand
        i = 1
        while True:
            cand = f"{prefix}{i}"
            if cand not in existing:
                return cand
            i += 1

    def _log(endpoint, workspace_id, credential_id, status_code, err_code=None, err_msg=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("clay_req_", logs),
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": err_code,
            "error_message": err_msg,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_or_quota(endpoint, workspace_id):
        policies = _load("rate_limits.json")
        if not isinstance(policies, list):
            policies = []
        per_minute = None
        per_day = None
        for p in policies:
            if not isinstance(p, dict):
                continue
            if p.get("workspace_id") not in (None, workspace_id):
                continue
            if p.get("endpoint") not in (None, endpoint):
                continue
            if isinstance(p.get("per_minute"), int):
                per_minute = p["per_minute"]
            if isinstance(p.get("per_day"), int):
                per_day = p["per_day"]
        if per_minute is None and per_day is None:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        one_min = now - datetime.timedelta(minutes=1)
        one_day = now - datetime.timedelta(days=1)

        def _ts(row):
            return _parse_iso(row.get("timestamp"))

        relevant = [r for r in logs if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("endpoint") == endpoint]
        if per_minute is not None:
            cnt = 0
            for r in relevant:
                dt = _ts(r)
                if dt is not None and dt >= one_min:
                    cnt += 1
            if cnt >= per_minute:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=per_minute, window="1m")
        if per_day is not None:
            cnt = 0
            for r in relevant:
                dt = _ts(r)
                if dt is not None and dt >= one_day:
                    cnt += 1
            if cnt >= per_day:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=per_day, window="24h")
        return None

    # ---- validate ----
    sd = _parse_iso(start_date)
    ed = _parse_iso(end_date)
    if sd is None:
        _log("getNotes", None, None, 400, "VALIDATION_ERROR", "start_date must be a valid ISO-8601 date-time")
        return _err("VALIDATION_ERROR", "start_date must be a valid ISO-8601 date-time", field="start_date")
    if ed is None:
        _log("getNotes", None, None, 400, "VALIDATION_ERROR", "end_date must be a valid ISO-8601 date-time")
        return _err("VALIDATION_ERROR", "end_date must be a valid ISO-8601 date-time", field="end_date")
    if ed <= sd:
        _log("getNotes", None, None, 400, "VALIDATION_ERROR", "end_date must be after start_date")
        return _err("VALIDATION_ERROR", "end_date must be after start_date", field="end_date")

    if contact_id is not None:
        if not isinstance(contact_id, str) or not re.match(r"^clay_ctc_[A-Za-z0-9]+$", contact_id):
            _log("getNotes", None, None, 400, "VALIDATION_ERROR", "Invalid contact_id")
            return _err("VALIDATION_ERROR", "Invalid contact_id", field="contact_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("getNotes", None, None, 400, "VALIDATION_ERROR", "limit out of range")
        return _err("VALIDATION_ERROR", "limit out of range", field="limit", minimum=1, maximum=200)

    if sort is None:
        sort = "created_at_desc"
    if sort not in ("created_at_asc", "created_at_desc"):
        _log("getNotes", None, None, 400, "VALIDATION_ERROR", "Invalid sort")
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort")

    # ---- load data ----
    notes = _load("notes.json")
    contacts = _load("contacts.json")
    workspaces = _load("workspaces.json")
    if not isinstance(notes, list):
        notes = []
    if not isinstance(contacts, list):
        contacts = []
    if not isinstance(workspaces, list):
        workspaces = []

    # ---- resolve ambient workspace ----
    # If contact_id given, workspace must be the contact's workspace.
    workspace_id = None
    if contact_id is not None:
        c = next((x for x in contacts if isinstance(x, dict) and x.get("id") == contact_id), None)
        if c is None or c.get("status") == "deleted":
            _log("getNotes", None, None, 404, "NOT_FOUND", "Contact not found")
            return _err("NOT_FOUND", "Contact not found")
        workspace_id = c.get("workspace_id")
        if not isinstance(workspace_id, str) or not workspace_id:
            _log("getNotes", None, None, 401, "UNAUTHORIZED", "Unauthorized")
            return _err("UNAUTHORIZED", "Unauthorized")
    else:
        # Choose a workspace that has notes in the range; else fall back to first workspace, else None.
        for n in notes:
            if not isinstance(n, dict):
                continue
            dt = _parse_iso(n.get("created_at"))
            if dt is None:
                continue
            if sd <= dt < ed:
                wid = n.get("workspace_id")
                if isinstance(wid, str) and wid:
                    workspace_id = wid
                    break
        if workspace_id is None:
            # pick any workspace if present; otherwise None
            for w in workspaces:
                if isinstance(w, dict) and isinstance(w.get("id"), str) and w.get("id"):
                    workspace_id = w["id"]
                    break

    # if still None, allow empty results but no auth context => unauthorized
    if workspace_id is None:
        _log("getNotes", None, None, 401, "UNAUTHORIZED", "Unauthorized")
        return _err("UNAUTHORIZED", "Unauthorized")

    rl = _rate_limit_or_quota("getNotes", workspace_id)
    if rl:
        _log("getNotes", workspace_id, None, 429, rl["error"]["code"], rl["error"]["message"])
        return rl

    # ---- cursor decode ----
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.startswith("off:"):
            _log("getNotes", workspace_id, None, 400, "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        try:
            offset = int(cursor.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("getNotes", workspace_id, None, 400, "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    # ---- filter (only by date range, workspace, and optional explicit contact_id) ----
    rows = []
    for n in notes:
        if not isinstance(n, dict):
            continue
        if n.get("workspace_id") != workspace_id:
            continue
        if n.get("status") == "deleted":
            continue
        if contact_id is not None and n.get("contact_id") != contact_id:
            continue
        dt = _parse_iso(n.get("created_at"))
        if dt is None:
            continue
        if sd <= dt < ed:
            rows.append(n)

    reverse = (sort == "created_at_desc")
    def _key(n):
        dt = _parse_iso(n.get("created_at"))
        # stable tie-breaker by id
        return (dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), n.get("id") or "")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = f"off:{offset + limit}"

    resp = {
        "notes": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None,
            "sort": sort
        }
    }
    _log("getNotes", workspace_id, None, 200, meta={"returned": len(page), "total": total})
    return resp

